<script setup lang="ts">
/**
 * A tool invocation shown as one expandable row (`design/components/tool-call.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tool-call.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/collapsible'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection, useTrackedSlots, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/tool-call.module.css'
import CodeBlock from '../structure/CodeBlock.vue'
import JsonTree from '../structure/JsonTree.vue'

export type ToolCallStatus = 'pending' | 'running' | 'done' | 'error' | 'denied' | 'approval'

export interface ToolCallMessages {
  input: string
  output: string
  status: Record<ToolCallStatus, string>
}

export interface ToolCallProps {
  defaultOpen?: boolean
  /**
   * The duration, preformatted by the app, such as "1.2s".
   */
  duration?: string
  /**
   * The tool's mark, `tool` by default, or `terminal`, `network` or `document` when the app
   * knows the kind.
   */
  icon?: IconRole
  /**
   * The arguments, rendered as JsonTree for a value or as CodeBlock for a string.
   */
  input?: unknown
  /**
   * The app's text for a failure or a refusal.
   */
  message?: string
  /**
   * All of the card's text (generic English defaults), which localized hosts replace.
   */
  messages?: ToolCallMessages
  /**
   * The tool's name as the model called it, such as `read_file` or `search_web`.
   */
  name: string
  open?: boolean
  status: 'error' | 'denied' | 'done' | 'pending' | 'running' | 'approval'
  /**
   * One line describing the call, such as the file read or the query run.
   */
  summary?: string
}

defineOptions({ name: 'ToolCall', inheritAttrs: false })

const props = withDefaults(defineProps<ToolCallProps>(), {
  defaultOpen: false,
  icon: 'tool',
  messages: () => ({
    input: 'Input',
    output: 'Output',
    status: {
      pending: 'Pending',
      running: 'Running',
      done: 'Done',
      error: 'Failed',
      denied: 'Denied',
      approval: 'Awaiting approval',
    },
  }),
  open: undefined,
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
const callerSlots = defineSlots<{ output?: (props: Record<string, never>) => unknown }>()
const slots = useTrackedSlots(callerSlots)
const uid = useId()
const trigger = useTemplateRef<HTMLElement>('trigger')
const running = computed(() => props.status === 'running')
const hasBody = computed(
  () => props.input !== undefined || Boolean(slots.output) || props.message !== undefined,
)
const statusIcon = computed(
  () =>
    (
      ({
        pending: 'time',
        running: 'loading',
        done: 'success',
        error: 'error',
        denied: 'denied',
        approval: 'help',
      }) as const
    )[props.status],
)
const documentDirection = useDirection(() => trigger.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    disabled: !hasBody.value,
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ToolCall',
    element: () => trigger.value,
    state: () => ({ status: props.status, expanded: api.value.open }),
    actions: {
      expand: () =>
        (() => {
          if (!hasBody.value) throw new Error('The call has nothing to show.')
          api.value.setOpen(true)
        })(),
      collapse: () => api.value.setOpen(false),
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    v-bind="api.getRootProps()"
    :class="styles.card"
    :data-status="status"
    :aria-busy="running ? true : undefined"
    data-member="tool-call"
  >
    <!-- trigger -->
    <button
      ref="trigger"
      v-bind="api.getTriggerProps()"
      :class="styles.trigger"
      :disabled="!hasBody"
    >
      <span :class="styles.mark">
        <Icon :name="icon" size="sm" />
      </span>
      <span :class="styles.name">
        {{ name }}
      </span>
      <span v-if="summary !== undefined" :class="styles.summary">
        {{ summary }}
      </span>
      <span :class="styles.trailing">
        <span v-if="duration !== undefined" :class="styles.duration">
          {{ duration }}
        </span>
        <span :class="[styles.status, running ? styles.spinning : undefined]">
          <Icon :name="statusIcon" size="sm" />
        </span>
        <span :class="styles.reader">
          {{ messages.status[status] }}
        </span>
        <span v-if="hasBody" :class="styles.chevron">
          <Icon name="down" size="sm" />
        </span>
      </span>
    </button>
    <!-- content -->
    <div
      v-if="hasBody"
      v-bind="api.getContentProps()"
      :class="styles.content"
      :style="{
        '--radix-collapsible-content-height': Object(api.getContentProps().style)['--height'],
      }"
    >
      <div :class="styles.inner">
        <div v-if="input !== undefined" :class="styles.section">
          <span :class="styles.heading">
            {{ messages.input }}
          </span>
          <CodeBlock v-if="typeof input === 'string'" :label="messages.input">
            {{ input }}
          </CodeBlock>
          <JsonTree v-else :data="input" :label="messages.input" :defaultDepth="1" />
        </div>
        <div v-if="$slots.output" :class="styles.section">
          <span :class="styles.heading">
            {{ messages.output }}
          </span>
          <slot name="output" />
        </div>
        <p v-if="message !== undefined" :class="styles.message">
          {{ message }}
        </p>
      </div>
    </div>
  </div>
</template>
